self.KB_CONTENT["card:752859"]={"id":"card:752859","ty":"card","sourceId":"752859","title":"『預算追加建立作業』的作業重點有哪些？","ver":"iGP","topic":"科目","keywords":["科目","預算"],"y":"explain","answer":"1.可以利用此作業，針對需要調整預算的期別資料做追加，系統會將追加後的金額更新到「科目/部門預算建立作業」。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
