self.KB_CONTENT["card:752235"]={"id":"card:752235","ty":"card","sourceId":"752235","title":"『密碼到期人員檢視表』的作業目的為何？","ver":"iGP","topic":"檢視表","keywords":["檢視表"],"y":"explain","answer":"供查看近期密碼將過期或已過期者之人員清單，並選擇是否發通知或設定有效截止日。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
