self.KB_CONTENT["card:779395"]={"id":"card:779395","ty":"card","sourceId":"779395","title":"『製令樹狀資訊查詢(IDL)』的作業目的為何？","ver":"GP4以上","topic":"製令","keywords":["製令","訂單","資訊","分析"],"y":"explain","answer":"可查詢某一製令之訂單，LRP或母製令之來源別，以樹狀圖來展開製令資訊，進一步分析之。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
