self.KB_CONTENT["card:782942"]={"id":"card:782942","ty":"card","sourceId":"782942","title":"『銀行資金預估狀況表』的作業目的為何？","ver":"GP4以上","topic":"狀況表","keywords":["狀況表","銀行","資金"],"y":"explain","answer":"列印某個截止日之銀行資金預估狀況，以供資金調度參考使用。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
