self.KB_CONTENT["card:755285"]={"id":"card:755285","ty":"card","sourceId":"755285","title":"『品號資料建立作業』中的『外包裝寬(CM) (MB094)』為何？","ver":"iGP","topic":"品號","keywords":["品號","大於","包裝","等於"],"y":"other","answer":"* 此欄位必須大於等於零。* 預設外包裝材積=長*寬*高*0.032808^3。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
