self.KB_CONTENT["card:888079"]={"id":"card:888079","ty":"card","sourceId":"888079","title":"憑證設計權限如何設定?","ver":"GP4.0.0.0 以上","topic":"憑證","keywords":["憑證","權限","設計"],"y":"howto","answer":"請在該使用者的『使用者權限建立作業』中，將該憑證程式代號權限設定成\"有\"【修改】權限即可。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
