self.KB_CONTENT["field:870937"]={"id":"field:870937","ty":"field","sourceId":"870937","title":"發票資料","ver":"iGP1.0.4.0以上","topic":"","keywords":[],"job":"結帳單建立作業","code":"","answer":"『結帳單建立作業-ACRI02』->【發票資料】頁籤的[發票稅額]是後續產生營業稅資料時會抓取此欄位金額；而單身[原幣/本幣稅額]則是拋帳與實際收款時會收到的稅額","file":"fields.jsonl"};
